from collections import Counter
def solve(gi,noise=8):
    H=len(gi);W=len(gi[0])
    # candidate periods: try all small h,w
    best=None
    for h in range(1,H+1):
        for w in range(1,W+1):
            pat=[[None]*w for _ in range(h)]
            ok=True
            for i in range(H):
                for j in range(W):
                    c=gi[i][j]
                    if c!=noise:
                        pi,pj=i%h,j%w
                        if pat[pi][pj] is not None and pat[pi][pj]!=c: ok=False;break
                        pat[pi][pj]=c
                if not ok:break
            if ok:
                out=[[pat[i%h][j%w] for j in range(W)] for i in range(H)]
                if best is None or h*w<h*best[0]: best=(h,w,out)
    return best
